// src/data/mockData.js
export const mockCurrentUser = {
    name: 'Super Admin',
    email: 'admin5@selo.com',
    role: 'Admin Nv.5'
};

export const mockAdmins = [
  { id: 1, name: 'Ana Costa', email: 'ana.costa@email.com', role: 'Admin Nv.1' },
  { id: 2, name: 'Bruno Lima', email: 'bruno.lima@email.com', role: 'Admin Nv.1' },
];

export const mockOngs = [
  { id: 1, name: 'Criança Feliz', responsible: 'Mariana Silva', email: 'contato@criancafeliz.org', phone: '(11) 98765-4321' },
  { id: 2, name: 'Planeta Verde', responsible: 'Carlos Pereira', email: 'contato@planetaverde.org', phone: '(21) 91234-5678' },
];

export const mockUsers = [
    { id: 1, name: 'João Silva', email: 'joao@email.com', seals: 150},
    { id: 2, name: 'Maria Oliveira', email: 'maria@email.com', seals: 275},
];

export const mockPrizes = [
    { id: 1, name: 'Ingresso de Cinema', cost: 50 },
    { id: 2, name: 'Vale-presente R$20', cost: 100 },
];
